module.exports = [{"id_kalimat":"amogenz_kalimat_021","teks_kalimat":"جَلَسَ الرَّجُلُ أَمَامَ الْبَيْتِ","analysis":[{"id_lafadz":"amogenz_lafadz_063","word":"جَلَسَ","steps":{"1":{"question":"Apa jenis kalimat جَلَسَ?","options":["Fi'il","Isim","Huruf"],"correct":"Fi'il","explanation":"Pekerjaan duduk di masa lampau."},"2":{"question":"Apa tanda/alasan جَلَسَ disebut Fi'il?","options":["Menerima Ta' Ta'nits","Tanwin","Al"],"correct":"Menerima Ta' Ta'nits","explanation":"Bisa berubah menjadi 'Jalasat'."},"3":{"question":"Apakah status جَلَسَ Mu'rob atau Mabni?","options":["Mabni","Mu'rob"],"correct":"Mabni","explanation":"Fi'il Madhi semuanya mabni."},"4":{"question":"Mengapa جَلَسَ berstatus Mabni?","options":["Kaidah Fi'il Madhi","Karena berharakat fathah","Karena pekerjaan"],"correct":"Kaidah Fi'il Madhi","explanation":"Hukum asal fi'il madhi adalah mabni."},"5":{"question":"Apa kedudukan I'rob/Mabni kata جَلَسَ?","options":["Mabni 'alal Fathi","Mabni 'alas Sukun","Mabni 'alad Dhammi"],"correct":"Mabni 'alal Fathi","explanation":"Berakhir dengan fathah dan tidak bersambung apapun."},"6":{"question":"Apa alasan جَلَسَ dihukumi Mabni 'alal Fathi?","options":["Tidak bersambung dhamir mutaharrik","Karena Isim Mufrad","Karena Fi'il Madhi"],"correct":"Tidak bersambung dhamir mutaharrik","explanation":"Tidak bertemu dengan 'Ta' subjek, 'Na' atau 'Nun' jamak."},"7":{"question":"Apa tanda I'rob/Mahal I'rob pada جَلَسَ?","options":["La Mahalla Lahu","Fathah","Sukun"],"correct":"La Mahalla Lahu","explanation":"Fi'il Madhi tidak memiliki kedudukan i'rob."},"8":{"question":"Mengapa tandanya menggunakan La Mahalla Lahu?","options":["Karena Mabni","Kaidah Fi'il","Karena awal kalimat"],"correct":"Karena Mabni","explanation":"Kata yang mabni tidak berkedudukan i'rob secara mahal kecuali jika ia jumlah."}}},{"id_lafadz":"amogenz_lafadz_064","word":"الرَّجُلُ","steps":{"1":{"question":"Apa jenis kalimat الرَّجُلُ?","options":["Isim","Fi'il","Huruf"],"correct":"Isim","explanation":"Menunjukkan orang (Laki-laki)."},"2":{"question":"Apa tanda/alasan الرَّجُلُ disebut Isim?","options":["Alif Lam (Al)","Tanwin","Idhafah"],"correct":"Alif Lam (Al)","explanation":"Memiliki awalan Al."},"3":{"question":"Apakah status الرَّجُلُ Mu'rob atau Mabni?","options":["Mu'rob","Mabni"],"correct":"Mu'rob","explanation":"Harakat akhirnya berubah."},"4":{"question":"Mengapa الرَّجُلُ berstatus Mu'rob?","options":["Isim Mutamakin","Karena Al","Karena Orang"],"correct":"Isim Mutamakin","explanation":"Bukan isim mabni."},"5":{"question":"Apa kedudukan I'rob/Mabni kata الرَّجُلُ?","options":["Rafa'","Nashab","Jarr"],"correct":"Rafa'","explanation":"Sebagai Fa'il (pelaku)."},"6":{"question":"Apa alasan الرَّجُلُ dihukumi Rafa'?","options":["Fa'il","Mubtada","Khabar"],"correct":"Fa'il","explanation":"Laki-laki tersebut yang melakukan duduk."},"7":{"question":"Apa tanda I'rob/Mahal I'rob pada الرَّجُلُ?","options":["Dhammah","Wawu","Alif"],"correct":"Dhammah","explanation":"Tanda rafa' utama."},"8":{"question":"Mengapa tandanya menggunakan Dhammah?","options":["Isim Mufrad","Jamak Taksir","Fi'il Mudhari'"],"correct":"Isim Mufrad","explanation":"Kata benda tunggal."}}},{"id_lafadz":"amogenz_lafadz_065","word":"أَمَامَ","steps":{"1":{"question":"Apa jenis kalimat أَمَامَ?","options":["Isim","Fi'il","Huruf"],"correct":"Isim","explanation":"Menunjukkan arah/tempat (Depan)."},"2":{"question":"Apa tanda/alasan أَمَامَ disebut Isim?","options":["Idhafah","Al","Tanwin"],"correct":"Idhafah","explanation":"Menjadi mudhaf kepada kata setelahnya."},"3":{"question":"Apakah status أَمَامَ Mu'rob atau Mabni?","options":["Mu'rob","Mabni"],"correct":"Mu'rob","explanation":"Termasuk Zharaf yang mu'rob."},"4":{"question":"Mengapa أَمَامَ berstatus Mu'rob?","options":["Bukan Zharaf Mabni","Karena Isim Mufrad","Karena letaknya"],"correct":"Bukan Zharaf Mabni","explanation":"Bisa berubah harakatnya (jarang) tapi di sini ia mu'rob manshub."},"5":{"question":"Apa kedudukan I'rob/Mabni kata أَمَامَ?","options":["Nashab","Rafa'","Jarr"],"correct":"Nashab","explanation":"Sebagai Zharaf Makan (Maf'ul Fih)."},"6":{"question":"Apa alasan أَمَامَ dihukumi Nashab?","options":["Zharaf Makan","Maf'ul Bih","Hal"],"correct":"Zharaf Makan","explanation":"Menjelaskan ruang/lokasi terjadinya perbuatan."},"7":{"question":"Apa tanda I'rob/Mahal I'rob pada أَمَامَ?","options":["Fathah","Kasrah","Sukun"],"correct":"Fathah","explanation":"Tanda nashab zharaf pada umumnya."},"8":{"question":"Mengapa tandanya menggunakan Fathah?","options":["Isim Mufrad","Isim Ghairu Munsharif","Jamak Taksir"],"correct":"Isim Mufrad","explanation":"Berbentuk mufrad."}}},{"id_lafadz":"amogenz_lafadz_066","word":"الْبَيْتِ","steps":{"1":{"question":"Apa jenis kalimat الْبَيْتِ?","options":["Isim","Fi'il","Huruf"],"correct":"Isim","explanation":"Nama benda (Rumah)."},"2":{"question":"Apa tanda/alasan الْبَيْتِ disebut Isim?","options":["Alif Lam (Al)","Tanwin","Jarr"],"correct":"Alif Lam (Al)","explanation":"Adanya Alif Lam."},"3":{"question":"Apakah status الْبَيْتِ Mu'rob atau Mabni?","options":["Mu'rob","Mabni"],"correct":"Mu'rob","explanation":"Berubah i'robnya karena amil."},"4":{"question":"Mengapa الْبَيْتِ berstatus Mu'rob?","options":["Isim Mutamakin","Karena Al","Karena Isim Mufrad"],"correct":"Isim Mutamakin","explanation":"Dapat menerima i'rob sepenuhnya."},"5":{"question":"Apa kedudukan I'rob/Mabni kata الْبَيْتِ?","options":["Jarr","Nashab","Rafa'"],"correct":"Jarr","explanation":"Sebagai Mudhaf Ilaih."},"6":{"question":"Apa alasan الْبَيْتِ dihukumi Jarr?","options":["Mudhaf Ilaih","Didahului Huruf Jarr","Sebagai Sifat"],"correct":"Mudhaf Ilaih","explanation":"Disandarkan pada zharaf sebelumnya (Depan Rumah)."},"7":{"question":"Apa tanda I'rob/Mahal I'rob pada الْبَيْتِ?","options":["Kasrah","Ya","Fathah"],"correct":"Kasrah","explanation":"Tanda jarr asli."},"8":{"question":"Mengapa tandanya menggunakan Kasrah?","options":["Isim Mufrad","Jamak Taksir","Jamak Muannas Salim"],"correct":"Isim Mufrad","explanation":"Kata benda tunggal."}}}]},{"id_kalimat":"amogenz_kalimat_022","teks_kalimat":"لَا تَلْعَبْ فِي الشَّارِعِ","analysis":[{"id_lafadz":"amogenz_lafadz_067","word":"لَا","steps":{"1":{"question":"Apa jenis kalimat لَا?","options":["Isim","Fi'il","Huruf"],"correct":"Huruf","explanation":"Kata ini tidak memiliki makna mandiri kecuali jika bersambung dengan kata lain, serta tidak menerima tanda-tanda isim maupun fi'il."},"2":{"question":"Apa fungsi لَا dalam kalimat ini?","options":["Laa Nafiyah (Penyangkalan)","Laa Nahi (Larangan)","Laa Athifah (Penyambung)"],"correct":"Laa Nahi (Larangan)","explanation":"Ia berfungsi sebagai tuntutan untuk meninggalkan suatu perbuatan (melarang) dan beramal menjazmkan fi'il mudhari' setelahnya."},"3":{"question":"Apakah status لَا Mu'rob atau Mabni?","options":["Mu'rob","Mabni"],"correct":"Mabni","explanation":"Semua jenis huruf dalam kaidah Nahwu bersifat Mabni, artinya harakat akhirnya tetap dan tidak akan pernah berubah oleh amil manapun."},"4":{"question":"Mengapa لَا berstatus Mabni?","options":["Karena merupakan Huruf","Karena bermakna larangan","Karena berakhiran alif"],"correct":"Karena merupakan Huruf","explanation":"Huruf adalah kategori kata yang statis dan tidak memiliki kedudukan i'rob secara mandiri (Laa mahalla laha)."},"5":{"question":"Apa dasar Mabni dari kata لَا?","options":["Mabni 'alas Sukun","Mabni 'alal Fathi","Mabni 'alad Dhammi"],"correct":"Mabni 'alas Sukun","explanation":"Kata ini berakhiran dengan huruf alif yang secara kaidah dianggap sebagai sukun mati."},"6":{"question":"Apa dampak لَا terhadap kata setelahnya?","options":["Menjadikannya Rafa'","Menjadikannya Nashab","Menjadikannya Jazm"],"correct":"Menjadikannya Jazm","explanation":"Laa An-Nahiyah termasuk dalam jajaran 'Jawazim' atau amil-amil yang wajib menjazmkan satu fi'il mudhari'."},"7":{"question":"Apa kedudukan I'rob dari huruf لَا?","options":["Rafa'","Nashab","Laa Mahalla Laha"],"correct":"Laa Mahalla Laha","explanation":"Huruf tidak menduduki posisi subjek, objek, atau keterangan sehingga tidak memiliki nilai i'rob (mahal)."},"8":{"question":"Mengapa disebut Laa Mahalla Laha?","options":["Karena Mabni asli dari kategori Huruf","Karena bermakna perintah","Karena berada di awal"],"correct":"Karena Mabni asli dari kategori Huruf","explanation":"Huruf hanya berfungsi sebagai alat bantu makna (harful ma'ani) tanpa menjadi rukun kalimat."}}},{"id_lafadz":"amogenz_lafadz_068","word":"تَلْعَبْ","steps":{"1":{"question":"Apa jenis kalimat تَلْعَبْ?","options":["Isim","Fi'il","Huruf"],"correct":"Fi'il","explanation":"Kata ini menunjukkan suatu perbuatan (bermain) yang terkait dengan dimensi waktu sekarang atau masa depan."},"2":{"question":"Apa tanda bahwa تَلْعَبْ adalah Fi'il?","options":["Tanwin","Diawali huruf Mudhara'ah","Adanya Alif Lam"],"correct":"Diawali huruf Mudhara'ah","explanation":"Terdapat huruf 'Ta' di awal sebagai ciri Fi'il Mudhari' untuk mukhathab (lawan bicara)."},"3":{"question":"Apakah status تَلْعَبْ Mu'rob atau Mabni?","options":["Mu'rob","Mabni"],"correct":"Mu'rob","explanation":"Fi'il mudhari' berstatus mu'rob selama tidak bersambung langsung dengan Nun Taukid atau Nun Niswah."},"4":{"question":"Mengapa تَلْعَبْ berstatus Mu'rob?","options":["Karena Fi'il Mudhari'","Karena bermakna larangan","Karena didahului Laa"],"correct":"Karena Fi'il Mudhari'","explanation":"Fi'il mudhari' adalah satu-satunya kategori kata kerja yang bisa berubah harakat akhirnya sesuai amil."},"5":{"question":"Apa kedudukan I'rob dari kata تَلْعَبْ?","options":["Rafa'","Nashab","Jazm"],"correct":"Jazm","explanation":"Lafadz ini dijazmkan karena didahului oleh amil jazm yaitu 'Laa Nahi'."},"6":{"question":"Apa alasan تَلْعَبْ dihukumi Jazm?","options":["Karena ada Laa An-Nahiyah","Karena sebagai Fa'il","Karena awal kalimat"],"correct":"Karena ada Laa An-Nahiyah","explanation":"Amil jawazim 'Laa' memaksa fi'il mudhari' setelahnya kehilangan harakat rafa'-nya."},"7":{"question":"Apa tanda I'rob Jazm pada تَلْعَبْ?","options":["Sukun","Fathah","Membuang Huruf Illat"],"correct":"Sukun","explanation":"Tanda jazm standar bagi fi'il yang huruf akhirnya sehat (bukan huruf illat)."},"8":{"question":"Mengapa tandanya menggunakan Sukun?","options":["Fi'il Mudhari' Shahih Akhir","Af'alul Khomsah","Isim Mufrad"],"correct":"Fi'il Mudhari' Shahih Akhir","explanation":"Huruf 'Ba' di akhir kata adalah huruf shahih, maka tanda jazm-nya adalah sukun zhahir (nampak)."}}}]},{"id_kalimat":"amogenz_kalimat_023","teks_kalimat":"السَّيَّارَةُ لَوْنُهَا أَحْمَرُ","analysis":[{"id_lafadz":"amogenz_lafadz_073","word":"السَّيَّارَةُ","steps":{"1":{"question":"Apa jenis kalimat السَّيَّارَةُ?","options":["Isim","Fi'il","Huruf"],"correct":"Isim","explanation":"Menunjukkan nama benda (Mobil)."},"2":{"question":"Apa tanda Isim pada السَّيَّارَةُ?","options":["Alif Lam (Al)","Tanwin","Huruf Jarr"],"correct":"Alif Lam (Al)","explanation":"Kata ini memiliki awalan 'Al' yang merupakan ciri khas kata benda."},"3":{"question":"Apakah status السَّيَّارَةُ Mu'rob atau Mabni?","options":["Mu'rob","Mabni"],"correct":"Mu'rob","explanation":"Harakat akhirnya dapat berubah sesuai kedudukannya dalam struktur kalimat."},"4":{"question":"Mengapa السَّيَّارَةُ berstatus Mu'rob?","options":["Isim Mutamakin","Karena benda mati","Karena Mufrad"],"correct":"Isim Mutamakin","explanation":"Ia adalah isim yang tidak menyerupai huruf sehingga menerima perubahan harakat."},"5":{"question":"Apa kedudukan I'rob السَّيَّارَةُ?","options":["Rafa'","Nashab","Jarr"],"correct":"Rafa'","explanation":"Ia berkedudukan sebagai subjek awal (Mubtada' Awwal) dalam kalimat isimiyah."},"6":{"question":"Apa alasan السَّيَّARAH dihukumi Rafa'?","options":["Mubtada'","Khabar","Fa'il"],"correct":"Mubtada'","explanation":"Mubtada' adalah isim marfu' yang sunyi dari amil lafdzi dan menjadi topik pembicaraan."},"7":{"question":"Apa tanda I'rob pada السَّيَّارَةُ?","options":["Dhammah","Alif","Wawu"],"correct":"Dhammah","explanation":"Tanda rafa' utama untuk isim yang bersifat tunggal."},"8":{"question":"Mengapa tandanya menggunakan Dhammah?","options":["Isim Mufrad","Jamak Taksir","Ghairu Munsharif"],"correct":"Isim Mufrad","explanation":"Karena lafadz ini menunjukkan makna tunggal."}}},{"id_lafadz":"amogenz_lafadz_074","word":"لَوْنُهَا","steps":{"1":{"question":"Apa jenis kata لَوْنُ dalam لَوْنُهَا?","options":["Isim","Fi'il","Huruf"],"correct":"Isim","explanation":"Menunjukkan makna warna, yang merupakan kategori nama sifat/benda."},"2":{"question":"Apa kedudukan لَوْنُ dalam struktur ini?","options":["Mubtada' Tsani (Kedua)","Khabar","Na'at"],"correct":"Mubtada' Tsani (Kedua)","explanation":"Ini adalah awal dari 'kalimat di dalam kalimat' yang akan menerangkan keadaan mobil."},"3":{"question":"Mengapa لَوْنُ berstatus Mu'rob?","options":["Isim Mutamakin","Karena Mudhaf","Karena dhamir"],"correct":"Isim Mutamakin","explanation":"Isim mufrad yang mampu menerima i'rob secara zahir."},"4":{"question":"Apa kedudukan I'rob لَوْنُ?","options":["Rafa'","Nashab","Jarr"],"correct":"Rafa'","explanation":"Sebagai Mubtada' (subjek kedua), ia wajib mengikuti hukum asal marfu'atul asma."},"5":{"question":"Apa fungsi 'HAA' (هَا) pada kata tersebut?","options":["Dhamir Mutashil (Mudhaf Ilaih)","Tanda Ta'nits","Huruf Tambahan"],"correct":"Dhamir Mutashil (Mudhaf Ilaih)","explanation":"Kata ganti yang kembali ke 'Mobil' dan berkedudukan sebagai pemilik (Mudhaf Ilaih)."},"6":{"question":"Apa status I'rob dhamir هَا?","options":["Mabni fi mahalli jarrin","Mu'rob Jarr","Mabni fi mahalli raf'in"],"correct":"Mabni fi mahalli jarrin","explanation":"Dhamir adalah mabni, namun karena posisinya sebagai Mudhaf Ilaih, ia menempati posisi Jarr."},"7":{"question":"Apa tanda I'rob pada لَوْنُ?","options":["Dhammah Zhahirah","Dhammah Muqaddarah","Alif"],"correct":"Dhammah Zhahirah","explanation":"Tanda rafa' yang tampak jelas di akhir kata."},"8":{"question":"Mengapa tandanya Dhammah?","options":["Isim Mufrad","Jamak Muannas","Mutsanna"],"correct":"Isim Mufrad","explanation":"Lafadz 'Lawnun' adalah bentuk tunggal."}}},{"id_lafadz":"amogenz_lafadz_075","word":"أَحْمَرُ","steps":{"1":{"question":"Apa jenis kalimat أَحْمَرُ?","options":["Isim","Fi'il","Huruf"],"correct":"Isim","explanation":"Menunjukkan warna merah (sifat)."},"2":{"question":"Apa kedudukan أَحْمَرُ dalam potongan kalimat 'Lawnuha Ahmar'?","options":["Khabar Mubtada' Tsani","Khabar Mubtada' Awwal","Na'at"],"correct":"Khabar Mubtada' Tsani","explanation":"Ia menjadi pelengkap berita bagi 'Warna' (Lawnun), bukan langsung bagi 'Mobil'."},"3":{"question":"Apa kedudukan I'rob dari أَحْمَرُ?","options":["Rafa'","Nashab","Jarr"],"correct":"Rafa'","explanation":"Khabar adalah isim yang wajib rafa' karena ia berfungsi menyempurnakan makna Mubtada."},"4":{"question":"Apa kedudukan 'Lawnuha Ahmar' secara utuh?","options":["Khabar Jumlah Ismiyah","Khabar Mufrad","Sifat"],"correct":"Khabar Jumlah Ismiyah","explanation":"Kesatuan kalimat ini secara kolektif menjadi berita bagi 'Mobil' (السَّيَّارَةُ)."},"5":{"question":"Apa status 'mahal' dari jumlah 'Lawnuha Ahmar'?","options":["Fi Mahalli Raf'in","Fi Mahalli Nashbin","Fi Mahalli Jarrin"],"correct":"Fi Mahalli Raf'in","explanation":"Karena ia menggantikan posisi Khabar yang seharusnya Rafa'."},"6":{"question":"Apa tanda I'rob pada أَحْمَرُ?","options":["Dhammah tanpa Tanwin","Dhammah dengan Tanwin","Fathah"],"correct":"Dhammah tanpa Tanwin","explanation":"Lafadz ini marfu' dengan tanda dhammah tunggal."},"7":{"question":"Mengapa أَحْمَرُ tidak menerima Tanwin?","options":["Karena Isim Ghairu Munsharif","Karena Alif Lam","Karena Mudhaf"],"correct":"Karena Isim Ghairu Munsharif","explanation":"Ia termasuk isim yang dilarang bertanwin karena mengikuti wazan 'Af'alu' (Sifat)."},"8":{"question":"Apa tanda I'rob-nya?","options":["Dhammah","Wawu","Alif"],"correct":"Dhammah","explanation":"Isim mufrad meskipun ghairu munsharif tetap rafa' dengan dhammah."}}}]},{"id_kalimat":"amogenz_kalimat_024","teks_kalimat":"سَافَرَ زَيْدٌ إِلَى حَضْرَمَوْتَ","analysis":[{"id_lafadz":"amogenz_lafadz_086","word":"سَافَرَ","steps":{"1":{"question":"Apa jenis kalimat سَافَرَ?","options":["Fi'il","Isim","Huruf"],"correct":"Fi'il","explanation":"Kata ini menunjukkan aktivitas (bepergian) yang telah selesai dilakukan."},"2":{"question":"Apa kategori Fi'il dari سَافَرَ?","options":["Madhi","Mudhari'","Amr"],"correct":"Madhi","explanation":"Bermakna 'telah bepergian', menunjukkan masa lampau."},"3":{"question":"Apakah status سَافَرَ Mu'rob atau Mabni?","options":["Mabni","Mu'rob"],"correct":"Mabni","explanation":"Hukum asal fi'il madhi adalah tetap (mabni) dan tidak dipengaruhi amil."},"4":{"question":"Apa dasar Mabni dari سَافَرَ?","options":["Mabni 'alal Fathi","Mabni 'alas Sukun","Mabni 'alad Dhammi"],"correct":"Mabni 'alal Fathi","explanation":"Huruf terakhirnya berharakat fathah karena tidak bersambung dengan dhamir rafa' mutaharrik."},"5":{"question":"Apa kedudukan I'rob-nya?","options":["Laa Mahalla Lahu","Fi Mahalli Raf'in","Fi Mahalli Nashbin"],"correct":"Laa Mahalla Lahu","explanation":"Fi'il Madhi tidak memiliki kedudukan i'rob dalam struktur kalimat utama."},"6":{"question":"Apa fungsi سَافَرَ dalam kalimat?","options":["Fi'il (Pekerjaan)","Mubtada'","Khabar"],"correct":"Fi'il (Pekerjaan)","explanation":"Bertindak sebagai unsur predikat dalam kalimat fi'liyah."},"7":{"question":"Apa tanda fisiknya?","options":["Fathah di akhir","Sukun","Dhammah"],"correct":"Fathah di akhir","explanation":"Harakat 'Ra' di akhir menunjukkan kemabniannya atas fathah."},"8":{"question":"Mengapa Mabni Fathah?","options":["Karena Fi'il Madhi Shahih Akhir","Karena awal kalimat","Karena Fa'ilnya mufrad"],"correct":"Karena Fi'il Madhi Shahih Akhir","explanation":"Setiap fi'il madhi yang tidak bertemu Wawu Jamak atau Dhamir Rafa' Mutaharrik wajib mabni fathah."}}},{"id_lafadz":"amogenz_lafadz_087","word":"زَيْدٌ","steps":{"1":{"question":"Apa jenis kalimat زَيْدٌ?","options":["Isim","Fi'il","Huruf"],"correct":"Isim","explanation":"Menunjukkan nama orang."},"2":{"question":"Apa status I'rob زَيْدٌ?","options":["Mu'rob","Mabni"],"correct":"Mu'rob","explanation":"Namanya dapat berubah harakat akhirnya tergantung fungsi kalimatnya."},"3":{"question":"Apa kedudukan زَيْدٌ dalam kalimat?","options":["Fa'il (Pelaku)","Maf'ul Bih","Mubtada'"],"correct":"Fa'il (Pelaku)","explanation":"Ia adalah subjek yang melakukan pekerjaan bepergian (Safara)."},"4":{"question":"Apa hukum I'rob bagi Fa'il?","options":["Rafa'","Nashab","Jarr"],"correct":"Rafa'","explanation":"Fa'il termasuk dalam 'Marfu'atul Asma' atau daftar isim yang wajib dibaca rafa'."},"5":{"question":"Apa tanda I'rob pada زَيْدٌ?","options":["Dhammah","Alif","Wawu"],"correct":"Dhammah","explanation":"Tanda rafa' standar untuk isim yang bukan jamak atau mutsanna."},"6":{"question":"Mengapa tandanya Dhammah?","options":["Isim Mufrad","Jamak Taksir","Asmaul Khomsah"],"correct":"Isim Mufrad","explanation":"Zaid adalah individu tunggal."},"7":{"question":"Apakah زَيْدٌ boleh menerima Tanwin?","options":["Ya, karena Isim Munsharif","Tidak, karena nama","Hanya jika Jarr"],"correct":"Ya, karena Isim Munsharif","explanation":"Meskipun nama orang, ia memenuhi syarat untuk menerima tanwin karena terdiri dari 3 huruf dengan tengah sukun."},"8":{"question":"Apa amil yang merofa'kan زَيْدٌ?","options":["Fi'il sebelumnya (Safara)","Mubtada'","Amil Maknawi"],"correct":"Fi'il sebelumnya (Safara)","explanation":"Fi'il bertugas memberikan status rafa' kepada pelaku (Fa'il)-nya."}}},{"id_lafadz":"amogenz_lafadz_088","word":"حَضْرَمَوْتَ","steps":{"1":{"question":"Apa jenis kalimat حَضْرَمَوْتَ?","options":["Isim","Fi'il","Huruf"],"correct":"Isim","explanation":"Menunjukkan nama tempat/wilayah."},"2":{"question":"Apa kedudukan I'rob حَضْرَمَوْتَ?","options":["Jarr","Nashab","Rafa'"],"correct":"Jarr","explanation":"Ia dijarrkan karena didahului oleh huruf jarr 'Ila'."},"3":{"question":"Apakah status حَضْرَمَوْتَ Mu'rob atau Mabni?","options":["Mu'rob","Mabni"],"correct":"Mu'rob","explanation":"Isim alam (nama) tempat umumnya bersifat mu'rob."},"4":{"question":"Apa tanda I'rob Jarr pada حَضْرَمَوْتَ?","options":["Fathah","Kasrah","Ya"],"correct":"Fathah","explanation":"Inilah keunikan isim ghairu munsharif; ia dijarrkan dengan fathah sebagai pengganti kasrah."},"5":{"question":"Mengapa tandanya menggunakan Fathah?","options":["Karena Isim Ghairu Munsharif","Karena Mudhaf","Karena Maf'ul Bih"],"correct":"Karena Isim Ghairu Munsharif","explanation":"Isim yang dilarang bertanwin tidak boleh menerima kasrah kecuali dalam kondisi tertentu."},"6":{"question":"Apa alasan حَضْرَمَوْتَ disebut Ghairu Munsharif?","options":["Tarkib Mazji","Adanya Alif Nun","Wazan Fi'il"],"correct":"Tarkib Mazji","explanation":"Kata ini adalah gabungan dua kata yang menyatu menjadi satu nama (Hadhara + Mawt)."},"7":{"question":"Apakah lafadz ini menerima Tanwin?","options":["Tidak","Ya","Kadang-kadang"],"correct":"Tidak","explanation":"Ciri utama Ghairu Munsharif adalah anti-tanwin."},"8":{"question":"Apa 'Illat' (alasan) hambatannya?","options":["Alamiyah + Tarkib Mazji","Alamiyah + Ta'nits","Alamiyah + 'Ujmah"],"correct":"Alamiyah + Tarkib Mazji","explanation":"Ia adalah nama (Alamiyah) dan merupakan susunan percampuran (Tarkib Mazji)."},"9":{"question":"Jelaskan Illat Tarkib Mazji pada kata ini!","options":["Penggabungan dua kata menjadi satu nama","Penambahan huruf di akhir","Kemiripan dengan kata kerja"],"correct":"Penggabungan dua kata menjadi satu nama","explanation":"Hadhramaut berasal dari kata 'Hadhara' dan 'Maut' yang dilebur menjadi identitas satu lokasi geografi."}}}]},{"id_kalimat":"amogenz_kalimat_025","teks_kalimat":"لَيْسَ أَحْمَدُ بِكَسْلَانَ","analysis":[{"id_lafadz":"amogenz_lafadz_089","word":"لَيْسَ","steps":{"1":{"question":"Apa jenis kalimat لَيْسَ?","options":["Isim","Fi'il","Huruf"],"correct":"Fi'il","explanation":"Meskipun bermakna negasi seperti huruf, secara struktural ia adalah Fi'il Jamid yang menerima tanda-tanda fi'il seperti Ta' Ta'nits."},"2":{"question":"Apa fungsi لَيْسَ dalam kalimat?","options":["Amil Nawasikh (Saudara Kaana)","Amil Nawashib","Amil Jawazim"],"correct":"Amil Nawasikh (Saudara Kaana)","explanation":"Ia merusak tatanan Mubtada dan Khabar; merofa'kan isim dan menashabkan khabar."},"3":{"question":"Apakah status لَيْسَ Mu'rob atau Mabni?","options":["Mabni","Mu'rob"],"correct":"Mabni","explanation":"Setiap Fi'il Madhi, termasuk yang jamid (statis) seperti Laisa, hukumnya adalah Mabni."},"4":{"question":"Apa dasar Mabni dari لَيْسَ?","options":["Mabni 'alal Fathi","Mabni 'alas Sukun","Mabni 'alad Dhammi"],"correct":"Mabni 'alal Fathi","explanation":"Karena ia adalah Fi'il Madhi yang tidak bersambung dengan dhamir rafa' mutaharrik maupun Wawu Jamak."},"5":{"question":"Apa kedudukan I'rob-nya?","options":["Laa Mahalla Lahu","Fi Mahalli Raf'in","Fi Mahalli Nashbin"],"correct":"Laa Mahalla Lahu","explanation":"Fi'il Madhi secara mandiri tidak menempati posisi i'rob dalam kalimat."},"6":{"question":"Apa dampak لَيْسَ terhadap Isim setelahnya?","options":["Merofa'kan Isim","Menashabkan Isim","Menjazmkan Isim"],"correct":"Merofa'kan Isim","explanation":"Sesuai kaidah: Tarfa'ul Isma wa Tanshibul Khabara (Merofa'kan Isim dan Menashabkan Khabar)."},"7":{"question":"Mengapa لَيْسَ disebut Fi'il Jamid?","options":["Tidak bisa ditashrif ke Mudhari/Amr","Karena bermakna tidak","Karena mabni"],"correct":"Tidak bisa ditashrif ke Mudhari/Amr","explanation":"Ia membeku dalam bentuk Madhi saja dan tidak memiliki bentuk turunan waktu lain."},"8":{"question":"Apa tanda kemabniannya?","options":["Fathah Zhahirah","Fathah Muqaddarah","Sukun"],"correct":"Fathah Zhahirah","explanation":"Fathah nampak jelas di atas huruf Sin."}}},{"id_lafadz":"amogenz_lafadz_090","word":"أَحْمَدُ","steps":{"1":{"question":"Apa kedudukan أَحْمَدُ dalam kalimat ini?","options":["Isim Laisa","Khabar Laisa","Fa'il"],"correct":"Isim Laisa","explanation":"Lafadz ini adalah subjek yang dimasuki oleh amil nawasikh Laisa."},"2":{"question":"Apa hukum I'rob untuk Isim Laisa?","options":["Rafa'","Nashab","Jarr"],"correct":"Rafa'","explanation":"Seluruh saudara Kaana (termasuk Laisa) wajib merofa'kan isimnya."},"3":{"question":"Apa tanda I'rob pada أَحْمَدُ?","options":["Dhammah","Wawu","Alif"],"correct":"Dhammah","explanation":"Tanda rafa' asli untuk isim mufrad."},"4":{"question":"Apakah أَحْمَدُ boleh menerima Tanwin?","options":["Tidak Boleh","Boleh","Wajib"],"correct":"Tidak Boleh","explanation":"Lafadz ini termasuk Isim Ghairu Munsharif yang dilarang menerima tanwin."},"5":{"question":"Apa jenis 'illat (alasan) pada أَحْمَدُ?","options":["Alamiyah + Wazan Fi'il","Alamiyah + Tarkib Mazji","Alamiyah + 'Ujmah"],"correct":"Alamiyah + Wazan Fi'il","explanation":"Ia adalah nama (Alamiyah) yang mengikuti pola kata kerja seperti 'Af'alu'."},"6":{"question":"Mengapa Wazan Fi'il menghalangi Tanwin?","options":["Karena menyerupai ciri Fi'il","Karena sulit diucapkan","Kaidah Pesantren"],"correct":"Karena menyerupai ciri Fi'il","explanation":"Isim yang polanya identik dengan kata kerja kehilangan hak tanwinnya karena tanwin adalah kekhasan isim."},"7":{"question":"Apa tanda rafa'-nya?","options":["Dhammah Zhahirah","Dhammah Muqaddarah","Fathah"],"correct":"Dhammah Zhahirah","explanation":"Meskipun ghairu munsharif, saat rafa' tandanya tetap dhammah yang nampak."},"8":{"question":"Apakah ia Mu'rob atau Mabni?","options":["Mu'rob","Mabni"],"correct":"Mu'rob","explanation":"Isim Ghairu Munsharif tetaplah mu'rob karena harakat akhirnya bisa berubah."},"9":{"question":"Sebutkan jumlah illat pada Ahmad!","options":["Dua Illat","Satu Illat","Tiga Illat"],"correct":"Dua Illat","explanation":"Yaitu 'Alamiyah (Nama) dan Wazan Fi'il (Pola Kata Kerja)."}}},{"id_lafadz":"amogenz_lafadz_091","word":"بِكَسْلَانَ","steps":{"1":{"question":"Apa fungsi huruf 'Ba' (بِ) pada بِكَسْلَانَ?","options":["Huruf Jarr Zaidah (Tambahan)","Huruf Jarr Ashli","Huruf Athaf"],"correct":"Huruf Jarr Zaidah (Tambahan)","explanation":"Ba' di sini berfungsi untuk memperkuat (taukid) makna peniadaan pada khabar Laisa."},"2":{"question":"Apa kedudukan كَسْلَانَ secara makna (mahal)?","options":["Khabar Laisa","Isim Laisa","Mudhaf Ilaih"],"correct":"Khabar Laisa","explanation":"Secara struktur ia dijarrkan huruf Ba, namun secara posisi ia adalah berita (khabar) bagi Laisa."},"3":{"question":"Apa hukum I'rob كَسْلَانَ karena ada huruf Ba?","options":["Majrur secara Lafadz","Manshub secara Lafadz","Marfu' secara Lafadz"],"correct":"Majrur secara Lafadz","explanation":"Karena didahului huruf jarr, maka harakatnya harus mengikuti kaidah jarr."},"4":{"question":"Apa tanda I'rob Jarr pada كَسْلَانَ?","options":["Fathah","Kasrah","Ya"],"correct":"Fathah","explanation":"Lafadz ini adalah Isim Ghairu Munsharif, maka saat jarr tandanya adalah fathah."},"5":{"question":"Mengapa كَسْلَانَ disebut Isim Ghairu Munsharif?","options":["Sifat + Alif Nun Tambahan","Alamiyah + Alif Nun","Sighat Muntahal Jumu'"],"correct":"Sifat + Alif Nun Tambahan","explanation":"Ia menunjukkan sifat (pemalas) dengan akhiran Alif dan Nun tambahan."},"6":{"question":"Apa wazan dari كَسْلَانَ?","options":["Fa'laan","Af'alu","Fu'aal"],"correct":"Fa'laan","explanation":"Pola sifat yang berakhiran -aan (alif dan nun)."},"7":{"question":"Apa status Mahal I'rob dari بِكَسْلَانَ?","options":["Fi Mahalli Nashbin","Fi Mahalli Raf'in","Fi Mahalli Jarrin"],"correct":"Fi Mahalli Nashbin","explanation":"Karena posisi aslinya adalah Khabar Laisa yang wajib Manshub."},"8":{"question":"Mengapa tidak dibaca Kasrah?","options":["Karena terhalang illat Ghairu Munsharif","Karena huruf Ba tambahan","Karena isim mufrad"],"correct":"Karena terhalang illat Ghairu Munsharif","explanation":"Isim Ghairu Munsharif dilarang menerima kasrah kecuali jika ber-Al atau menjadi Mudhaf."},"9":{"question":"Sebutkan dua illat pada Kaslan!","options":["Washfiyah (Sifat) & Alif Nun Za'idatain","Alamiyah & Alif Nun","Washfiyah & Wazan Fi'il"],"correct":"Washfiyah (Sifat) & Alif Nun Za'idatain","explanation":"Makna sifat dan adanya tambahan alif-nun di akhir kata."}}}]},{"id_kalimat":"amogenz_kalimat_026","teks_kalimat":"جَاءَ الْقَاضِي إِلَى النَّادِي","analysis":[{"id_lafadz":"amogenz_lafadz_096","word":"الْقَاضِي","steps":{"1":{"question":"Apa kedudukan الْقَاضِي dalam kalimat ini?","options":["Fa'il","Maf'ul Bih","Mubtada"],"correct":"Fa'il","explanation":"Lafadz ini adalah pelaku dari pekerjaan 'datang' (jaa'a)."},"2":{"question":"Apa jenis isim dari lafadz الْقَاضِي?","options":["Isim Manqush","Isim Maqshur","Isim Mamdud"],"correct":"Isim Manqush","explanation":"Isim mu'rob yang diakhiri huruf Ya' lazimah (menetap) dan didahului harakat kasrah."},"3":{"question":"Apa hukum I'rob bagi Fa'il?","options":["Rafa'","Nashab","Jarr"],"correct":"Rafa'","explanation":"Setiap pelaku (Fa'il) dalam kaidah Nahwu wajib Marfu'."},"4":{"question":"Apa tanda I'rob pada الْقَاضِي?","options":["Dhammah Muqaddarah","Dhammah Zhahirah","Tasyid"],"correct":"Dhammah Muqaddarah","explanation":"Tanda rafa'-nya adalah dhammah yang disembunyikan di atas huruf Ya'."},"5":{"question":"Mengapa dhammah-nya tidak nampak (Muqaddarah)?","options":["Tsiqal (Berat)","Ta'azzur (Mustahil)","Munasabah"],"correct":"Tsiqal (Berat)","explanation":"Mengucapkan dhammah di atas huruf Ya' setelah kasrah terasa berat bagi lisan orang Arab."},"6":{"question":"Apakah Al-Qadhi Mu'rob atau Mabni?","options":["Mu'rob","Mabni"],"correct":"Mu'rob","explanation":"Isim Manqush adalah isim mu'rob, hanya saja tanda i'robnya diperkirakan pada kondisi tertentu."},"7":{"question":"Bagaimana jika الْقَاضِي dalam posisi Nashab?","options":["Fathah Zhahirah","Fathah Muqaddarah","Tetap Sukun"],"correct":"Fathah Zhahirah","explanation":"Berbeda dengan Rafa'/Jarr, harakat Fathah dianggap ringan (khafif) di atas Ya' sehingga wajib nampak."},"8":{"question":"Apa syarat disebut Isim Manqush?","options":["Berakhir Ya' dan sebelumnya Kasrah","Berakhir Alif dan sebelumnya Fathah","Berakhir Hamzah"],"correct":"Berakhir Ya' dan sebelumnya Kasrah","explanation":"Ciri khas Manqush adalah pola -Iiy (Kasrah + Ya)."}}}]},{"id_kalimat":"amogenz_kalimat_027","teks_kalimat":"إِنَّ أَخَاكَ ذُو أَدَبٍ","analysis":[{"id_lafadz":"amogenz_lafadz_103","word":"أَخَاكَ","steps":{"1":{"question":"Apa kedudukan أَخَاكَ dalam kalimat ini?","options":["Isim Inna","Khabar Inna","Fa'il"],"correct":"Isim Inna","explanation":"Lafadz ini terletak setelah Inna dan berfungsi sebagai subjek yang ditekankan."},"2":{"question":"Apa hukum I'rob untuk Isim Inna?","options":["Nashab","Rafa'","Jarr"],"correct":"Nashab","explanation":"Amil 'Inna' bertugas menashabkan isim dan merofa'kan khabar."},"3":{"question":"Apa kategori kata dari أَخَا?","options":["Asmaul Khamsah","Isim Mutsanna","Isim Mufrad"],"correct":"Asmaul Khamsah","explanation":"Termasuk dalam jajaran 'Nama-Nama yang Lima' (Abun, Akhun, Hamun, Fuu, Dzu)."},"4":{"question":"Apa tanda Nashab bagi Asmaul Khamsah?","options":["Alif","Fathah","Ya"],"correct":"Alif","explanation":"Asmaul Khamsah di-i'rob dengan huruf, dan tanda nashabnya adalah Alif."},"5":{"question":"Mengapa ia menggunakan tanda Alif (Bukan Fathah)?","options":["Karena memenuhi syarat Asmaul Khamsah","Karena Isim Mutsanna","Karena Mudhaf Ilaih"],"correct":"Karena memenuhi syarat Asmaul Khamsah","explanation":"Ia berbentuk mufrad (tunggal), mudhaf (disandarkan), dan mudhaf-nya bukan ke Ya' Mutakallim."},"6":{"question":"Kepada siapa lafadz أَخَا disandarkan (Mudhaf)?","options":["Kaf Khitab (Dhamir Kamu)","Zaid","Inna"],"correct":"Kaf Khitab (Dhamir Kamu)","explanation":"Huruf 'Ka' di akhir berfungsi sebagai Mudhaf Ilaih."},"7":{"question":"Apa kedudukan 'Ka' (كَ) tersebut?","options":["Fi Mahalli Jarrin (Mudhaf Ilaih)","Fi Mahalli Nashbin","Huruf Tambahan"],"correct":"Fi Mahalli Jarrin (Mudhaf Ilaih)","explanation":"Setiap dhamir yang bersambung dengan isim pasti berkedudukan Jarr sebagai Mudhaf Ilaih."},"8":{"question":"Apa syarat utama i'rob huruf pada Asmaul Khamsah?","options":["Harus Mudhaf kepada selain Ya' Mutakallim","Harus Jamak","Harus Mabni"],"correct":"Harus Mudhaf kepada selain Ya' Mutakallim","explanation":"Jika mudhaf ke Ya' Mutakallim (seperti 'Akhii'), maka i'robnya kembali menggunakan harakat muqaddarah."}}},{"id_lafadz":"amogenz_lafadz_104","word":"ذُو","steps":{"1":{"question":"Apa kedudukan ذُو dalam kalimat ini?","options":["Khabar Inna","Isim Inna","Sifat"],"correct":"Khabar Inna","explanation":"Lafadz ini menyempurnakan berita tentang 'saudaramu' (Isim Inna)."},"2":{"question":"Apa hukum I'rob bagi Khabar Inna?","options":["Rafa'","Nashab","Jarr"],"correct":"Rafa'","explanation":"Inna merofa'kan khabarnya."},"3":{"question":"Apa tanda Rafa' bagi lafadz ذُو?","options":["Wawu","Dhammah","Alif"],"correct":"Wawu","explanation":"Lafadz 'Dzu' adalah bagian dari Asmaul Khamsah yang tanda rafa'-nya menggunakan Wawu."},"4":{"question":"Apa arti dari ذُو dalam konteks ini?","options":["Pemilik","Yang itu","Saudara"],"correct":"Pemilik","explanation":"Dzu bermakna 'Shahib' atau pemilik (pemilik adab)."},"5":{"question":"Apa syarat khusus bagi kata ذُو agar masuk Asmaul Khamsah?","options":["Bermakna Shahib & Mudhaf ke Isim Zhahir","Harus Jamak","Harus ber-Al"],"correct":"Bermakna Shahib & Mudhaf ke Isim Zhahir","explanation":"Dzu tidak bisa berdiri sendiri dan harus disandarkan pada kata benda nampak (bukan dhamir)."},"6":{"question":"Apakah ذُو Mu'rob atau Mabni?","options":["Mu'rob","Mabni"],"correct":"Mu'rob","explanation":"Ia mu'rob dengan tanda huruf (Wawu/Alif/Ya)."},"7":{"question":"Apa kedudukan 'Adabin' (أَدَبٍ) setelahnya?","options":["Mudhaf Ilaih","Maf'ul Bih","Khabar"],"correct":"Mudhaf Ilaih","explanation":"Isim setelah 'Dzu' wajib dibaca Jarr sebagai Mudhaf Ilaih."},"8":{"question":"Mengapa tandanya Wawu?","options":["Karena Asmaul Khamsah dalam posisi Rafa'","Karena Jamak Mudzakkar","Karena Isim Mufrad"],"correct":"Karena Asmaul Khamsah dalam posisi Rafa'","explanation":"Wawu adalah pengganti Dhammah pada kelompok kata ini."}}}]},{"id_kalimat":"amogenz_kalimat_028","teks_kalimat":"هَذَا الْفَتَى يَحْمِلُ عَصًا","analysis":[{"id_lafadz":"amogenz_lafadz_109","word":"الْفَتَى","steps":{"1":{"question":"Apa kedudukan الْفَتَى dalam kalimat ini?","options":["Badal / Athaf Bayan","Khabar","Mubtada"],"correct":"Badal / Athaf Bayan","explanation":"Isim ber-Al setelah isim isyarah (Hadza) umumnya berkedudukan sebagai Badal (Pengganti)."},"2":{"question":"Apa jenis isim dari الْفَتَى?","options":["Isim Maqshur","Isim Manqush","Isim Mamdud"],"correct":"Isim Maqshur","explanation":"Isim mu'rob yang diakhiri Alif Lazimah (menetap) dalam bentuk menyerupai Ya'."},"3":{"question":"Apa hukum I'rob dari الْفَتَى di sini?","options":["Rafa'","Nashab","Jarr"],"correct":"Rafa'","explanation":"Karena ia mengikuti 'Hadza' yang berkedudukan sebagai Mubtada (Marfu')."},"4":{"question":"Apa tanda I'rob pada الْفَتَى?","options":["Dhammah Muqaddarah","Dhammah Zhahirah","Fathah"],"correct":"Dhammah Muqaddarah","explanation":"Semua tanda i'rob pada Isim Maqshur disembunyikan di atas Alif."},"5":{"question":"Mengapa harakatnya tidak nampak?","options":["Ta'azzur (Mustahil)","Tsiqal (Berat)","Munasabah"],"correct":"Ta'azzur (Mustahil)","explanation":"Secara teknis, mustahil meletakkan harakat vokal (A/I/U) di atas huruf Alif mati."},"6":{"question":"Apakah Al-Fata Mu'rob atau Mabni?","options":["Mu'rob","Mabni"],"correct":"Mu'rob","explanation":"Meskipun bentuk akhirnya statis, ia tetap dianggap mu'rob secara 'perkiraan' (taqdiri)."},"7":{"question":"Bagaimana i'rob-nya jika ia menjadi objek (Nashab)?","options":["Fathah Muqaddarah","Fathah Zhahirah","Tanwin"],"correct":"Fathah Muqaddarah","explanation":"Tetap tidak nampak karena alasan Ta'azzur yang sama."},"8":{"question":"Apa ciri utama Isim Maqshur?","options":["Berakhir Alif sebelumnya Fathah","Berakhir Ya sebelumnya Kasrah","Berakhir Hamzah"],"correct":"Berakhir Alif sebelumnya Fathah","explanation":"Pola utamanya adalah -Aa (Fathah + Alif)."}}},{"id_lafadz":"amogenz_lafadz_111","word":"عَصًا","steps":{"1":{"question":"Apa kedudukan عَصًا dalam kalimat?","options":["Maf'ul Bih (Objek)","Fa'il","Khabar"],"correct":"Maf'ul Bih (Objek)","explanation":"Lafadz ini adalah benda yang dibawa (yahmilu)."},"2":{"question":"Apa jenis isim dari lafadz عَصًا?","options":["Isim Maqshur","Isim Manqush","Isim Mufrad Shahih"],"correct":"Isim Maqshur","explanation":"Meskipun ada tanwin, huruf aslinya adalah Alif (berbentuk tegak)."},"3":{"question":"Apa hukum I'rob bagi Maf'ul Bih?","options":["Nashab","Rafa'","Jarr"],"correct":"Nashab","explanation":"Objek wajib dibaca Manshub."},"4":{"question":"Apa tanda I'rob Nashab pada عَصًا?","options":["Fathah Muqaddarah","Fathah Zhahirah (Tanwin)","Sukun"],"correct":"Fathah Muqaddarah","explanation":"Sama seperti Al-Fata, tandanya diperkirakan di atas Alif."},"5":{"question":"Jika tandanya Muqaddarah, lalu apa bunyi tanwin 'An' di situ?","options":["Tanwin Ghad (Pengganti)","Tanda Nashab","Harakat Asli"],"correct":"Tanwin Ghad (Pengganti)","explanation":"Tanwin pada isim maqshur nakirah bukan tanda i'rob, melainkan penanda bahwa alif-nya bertemu sukun tanwin."},"6":{"question":"Mengapa disebut Ta'azzur?","options":["Karena Alif tidak menerima harakat","Karena sulit dibaca","Karena ada tanwin"],"correct":"Karena Alif tidak menerima harakat","explanation":"Alif adalah huruf yang selamanya sukun, sehingga vokal apapun tidak bisa muncul di sana."},"7":{"question":"Apakah ia Mu'rob?","options":["Ya, Mu'rob Taqdiri","Tidak, Mabni","Mu'rob Lafdzi"],"correct":"Ya, Mu'rob Taqdiri","explanation":"Perubahan statusnya ada, namun tidak terlihat secara lisan."},"8":{"question":"Bagaimana tanda Jarr-nya?","options":["Kasrah Muqaddarah","Fathah Muqaddarah","Kasrah Zhahirah"],"correct":"Kasrah Muqaddarah","explanation":"Dalam semua kondisi (Rafa/Nashab/Jarr), tanda i'robnya selalu Muqaddarah 'alat Ta'azzur."}}}]},{"id_kalimat":"amogenz_kalimat_029","teks_kalimat":"رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًا","analysis":[{"id_lafadz":"amogenz_lafadz_112","word":"أَحَدَ عَشَرَ","steps":{"1":{"question":"Apa jenis kalimat أَحَدَ عَشَرَ?","options":["Isim (Adad)","Fi'il","Huruf"],"correct":"Isim (Adad)","explanation":"Ini adalah kata bilangan (Adad) yang menunjukkan jumlah sebelas."},"2":{"question":"Bagaimana struktur kata أَحَدَ عَشَرَ?","options":["Adad Murakkab","Adad Mufrad","Adad Ma'thuf"],"correct":"Adad Murakkab","explanation":"Adad Murakkab adalah bilangan 11-19 yang tersusun dari dua bagian tanpa huruf athaf."},"3":{"question":"Apakah status أَحَدَ عَشَرَ Mu'rob atau Mabni?","options":["Mabni","Mu'rob"],"correct":"Mabni","explanation":"Adad Murakkab (kecuali angka 12) bersifat mabni pada kedua bagiannya."},"4":{"question":"Apa dasar kemabnian أَحَدَ عَشَرَ?","options":["Mabni 'ala fathi al-juz'aini","Mabni 'alas sukun","Mabni 'alal fathi"],"correct":"Mabni 'ala fathi al-juz'aini","explanation":"Kedua bagiannya (ahada dan 'asyara) selalu berharakat fathah terlepas dari kedudukannya."},"5":{"question":"Apa kedudukan (Mahal) أَحَدَ عَشَرَ dalam kalimat ini?","options":["Fi Mahalli Nashbin (Maf'ul Bih)","Fi Mahalli Raf'in (Fa'il)","Fi Mahalli Jarrin"],"correct":"Fi Mahalli Nashbin (Maf'ul Bih)","explanation":"Ia menjadi objek (yang dilihat) dari fi'il Ra'aitu."},"6":{"question":"Mengapa ia menempati posisi Nashab?","options":["Karena objek dari kata kerja","Karena sebagai keterangan","Karena jatuh setelah fi'il"],"correct":"Karena objek dari kata kerja","explanation":"Dalam struktur Fi'il + Fa'il (Ra'aitu), kata selanjutnya yang menerima aksi adalah Maf'ul Bih."},"7":{"question":"Apa tanda i'rob keseluruhannya?","options":["Mabni 'ala fathi al-juz'aini","Fathah","Sukun"],"correct":"Mabni 'ala fathi al-juz'aini","explanation":"Hukum asalnya tetap mabni, namun posisinya (mahal) adalah nashab."},"8":{"question":"Apa istilah untuk kedua bagian bilangan ini?","options":["Juz'ul Awwal & Juz'uts Tsani","Mubtada' & Khabar","Mudhaf & Mudhaf Ilaih"],"correct":"Juz'ul Awwal & Juz'uts Tsani","explanation":"Istilah teknis untuk bagian pertama dan kedua dari bilangan susun."}}},{"id_lafadz":"amogenz_lafadz_113","word":"كَوْكَبًا","steps":{"1":{"question":"Apa kedudukan كَوْكَبًا dalam kalimat ini?","options":["Tamyiz","Maf'ul Bih","Hal"],"correct":"Tamyiz","explanation":"Isim nakirah manshub yang menjelaskan ketidakjelasan (ibham) pada bilangan sebelumnya."},"2":{"question":"Apa jenis Tamyiz pada lafadz ini?","options":["Tamyiz Dzati (Adad)","Tamyiz Nisbah","Tamyiz Kayl"],"correct":"Tamyiz Dzati (Adad)","explanation":"Ia menjelaskan zat dari bilangan yang disebutkan sebelumnya."},"3":{"question":"Apa hukum i'rob bagi Tamyiz bilangan 11-99?","options":["Wajib Nashab","Wajib Jarr","Boleh Rafa'"],"correct":"Wajib Nashab","explanation":"Berdasarkan kaidah Adad, ma'dud (benda yang dihitung) untuk angka 11-99 harus mufrad manshub."},"4":{"question":"Apa tanda i'rob pada كَوْكَبًا?","options":["Fathah","Kasrah","Tanwin Dhammah"],"correct":"Fathah","explanation":"Tanda asli nashab bagi isim mufrad."},"5":{"question":"Apakah ia Mu'rob atau Mabni?","options":["Mu'rob","Mabni"],"correct":"Mu'rob","explanation":"Isim mufrad nakirah yang menerima perubahan i'rob secara jelas."},"6":{"question":"Mengapa harus Nakirah?","options":["Syarat Tamyiz","Syarat Fa'il","Syarat Mudhaf"],"correct":"Syarat Tamyiz","explanation":"Hukum asal tamyiz adalah nakirah."},"7":{"question":"Apa amil yang menashabkan كَوْكَبًا?","options":["Isim Adad (Bilangan)","Fi'il Ra'aitu","Huruf"],"correct":"Isim Adad (Bilangan)","explanation":"Bilangan 'sebelas' itulah yang bekerja memberikan hukum nashab pada penjelasnya."},"8":{"question":"Bagaimana bunyi kaidah Ma'dud 11-99?","options":["Mufrad Manshub","Jamak Majrur","Mufrad Majrur"],"correct":"Mufrad Manshub","explanation":"Aturan baku dalam bab Adad wa Ma'dud."}}}]},{"id_kalimat":"amogenz_kalimat_030","teks_kalimat":"نَحْنُ أُولُو قُوَّةٍ وَبَأْسٍ","analysis":[{"id_lafadz":"amogenz_lafadz_117","word":"أُولُو","steps":{"1":{"question":"Apa kedudukan أُولُو dalam kalimat ini?","options":["Khabar","Mubtada'","Na'at"],"correct":"Khabar","explanation":"Ia menjadi pelengkap berita bagi dhomir 'Nahnu' (Mubtada')."},"2":{"question":"Apa hukum i'rob bagi Khabar?","options":["Rafa'","Nashab","Jarr"],"correct":"Rafa'","explanation":"Khabar termasuk dalam kelompok Marfu'atul Asma (Isim-isim yang wajib rafa')."},"3":{"question":"Apa jenis isim dari lafadz أُولُو?","options":["Mulhaq bi Jam'il Mudzakkaris Salim","Jamak Mudzakkar Salim Ashli","Asmaul Khamsah"],"correct":"Mulhaq bi Jam'il Mudzakkaris Salim","explanation":"Lafadz yang tidak memiliki bentuk mufrod dari jenisnya sendiri namun mengikuti i'rob jamak mudzakkar salim."},"4":{"question":"Apa tanda rafa' bagi lafadz أُولُو?","options":["Wawu","Dhammah","Alif"],"correct":"Wawu","explanation":"Karena ia mulhaq (ikut) pada jamak mudzakkar salim, maka tanda rafa'-nya adalah Wawu."},"5":{"question":"Mengapa ia disebut 'Mulhaq'?","options":["Karena tidak punya mufrod sewazan","Karena ia mabni","Karena bermakna banyak"],"correct":"Karena tidak punya mufrod sewazan","explanation":"Lafadz ini tidak memiliki bentuk tunggal (mufrod) yang lafadznya sama, mufrodnya adalah 'Dzu'."},"6":{"question":"Apakah أُولُو berfungsi sebagai Mudhaf?","options":["Ya, Wajib Mudhaf","Tidak","Kadang-kadang"],"correct":"Ya, Wajib Mudhaf","explanation":"Lafadz Ulu (pemilik) tidak bisa berdiri sendiri dan harus disandarkan pada isim setelahnya."},"7":{"question":"Apa tanda nasob/jarr dari أُولُو?","options":["Uulii (Ya')","Uuluuna","Uulaa"],"correct":"Uulii (Ya')","explanation":"Sama seperti jamak mudzakkar salim, tanda nasob dan jarr-nya adalah Ya'."},"8":{"question":"Apa kedudukan 'Quwwatin' (قُوَّةٍ) setelahnya?","options":["Mudhaf Ilaih","Sifat","Tamyiz"],"correct":"Mudhaf Ilaih","explanation":"Isim yang jatuh setelah Ulu berstatus sebagai pemilik sandaran makna."}}}]},{"id_kalimat":"amogenz_kalimat_031","teks_kalimat":"مَا قَامَ إِلَّا زَيْدٌ","analysis":[{"id_lafadz":"amogenz_lafadz_118","word":"مَا","steps":{"1":{"question":"Apa jenis kalimat مَا di sini?","options":["Huruf Nafi","Isim Istifham","Isim Maushul"],"correct":"Huruf Nafi","explanation":"Berfungsi untuk meniadakan atau menyangkal perbuatan (tidak berdiri)."},"2":{"question":"Apakah مَا ini beramal (bekerja)?","options":["Ghairu 'Amilah","Beramal seperti Laisa","Menashabkan Fi'il"],"correct":"Ghairu 'Amilah","explanation":"Ma nafi yang masuk pada fi'il madhi tidak merubah i'rob fi'il tersebut."},"3":{"question":"Status مَا adalah?","options":["Mabni","Mu'rob"],"correct":"Mabni","explanation":"Seluruh huruf adalah mabni."},"4":{"question":"Apa dasar kemabnian مَا?","options":["Mabni 'alas Sukun","Mabni 'alal Fathi","Mabni 'alad Dhammi"],"correct":"Mabni 'alas Sukun","explanation":"Berakhir dengan alif yang merupakan tanda sukun mati."},"5":{"question":"Kedudukan I'robnya?","options":["Laa Mahalla Laha","Fi Mahalli Raf'in","Fi Mahalli Nashbin"],"correct":"Laa Mahalla Laha","explanation":"Huruf tidak memiliki tempat dalam i'rob."},"6":{"question":"Apa arti مَا dalam kalimat ini?","options":["Tidak","Apa","Sesuatu"],"correct":"Tidak","explanation":"Menunjukkan penyangkalan terhadap kata kerja setelahnya."},"7":{"question":"Apa pengaruhnya terhadap 'Qaama'?","options":["Hanya makna, tidak ada i'rob","Merofa'kan","Menjazmkan"],"correct":"Hanya makna, tidak ada i'rob","explanation":"Status i'rob Qaama tetap mabni fathah."},"8":{"question":"Disebut apakah pola kalimat yang diawali Nafi?","options":["Manfi","Mutsbat","Majhul"],"correct":"Manfi","explanation":"Kalimat yang mengandung unsur negasi/penyangkalan."}}},{"id_lafadz":"amogenz_lafadz_119","word":"إِلَّا","steps":{"1":{"question":"Apa fungsi إِلَّا dalam kalimat ini?","options":["Adatul Hashr / Malghah","Adatul Istitsna' (Pengecualian)","Huruf Athaf"],"correct":"Adatul Hashr / Malghah","explanation":"Karena kalimatnya Naqish Mufarragh (sebelum illa tidak ada Mustatsna Minhu), maka fungsinya hanya sebagai pembatas (Qashr)."},"2":{"question":"Apakah إِلَّا di sini bekerja menashabkan?","options":["Tidak (Dibatalkan)","Ya","Kadang-kadang"],"correct":"Tidak (Dibatalkan)","explanation":"Dalam gaya bahasa mufarragh, Illa tidak beramal secara i'rob."},"3":{"question":"Apa status I'rob إِلَّا?","options":["Mabni 'alas Sukun","Mu'rob","Mabni 'alal Fathi"],"correct":"Mabni 'alas Sukun","explanation":"Seluruh huruf istitsna' adalah mabni."},"4":{"question":"Apakah ia memiliki Mahal I'rob?","options":["Tidak (Laa Mahalla Laha)","Fi Mahalli Nashbin","Fi Mahalli Raf'in"],"correct":"Tidak (Laa Mahalla Laha)","explanation":"Sesuai hukum asal huruf."},"5":{"question":"Mengapa disebut 'Malghah'?","options":["Karena fungsinya dibatalkan","Karena bermakna kecuali","Karena berada di tengah"],"correct":"Karena fungsinya dibatalkan","explanation":"Maksudnya tidak bekerja merubah i'rob isim setelahnya menjadi manshub."},"6":{"question":"Apa syarat Illa bekerja sebagai istitsna'?","options":["Kalimat harus Taam (Lengkap)","Kalimat harus Manfi","Kalimat harus Pendek"],"correct":"Kalimat harus Taam (Lengkap)","explanation":"Harus ada penyebutan kelompok besar yang dikecualikan (Mustatsna Minhu)."},"7":{"question":"Disebut apakah gaya bahasa 'Maa ... Illa ...'?","options":["Qashr (Pembatasan)","Nida'","Ighra'"],"correct":"Qashr (Pembatasan)","explanation":"Hanya Zaid lah yang berdiri."},"8":{"question":"Bagaimana cara menentukan i'rob setelah Illa pada tipe ini?","options":["Anggap 'Maa' dan 'Illa' tidak ada","Wajib Nashab","Wajib Jarr"],"correct":"Anggap 'Maa' dan 'Illa' tidak ada","explanation":"Metode praktis untuk menentukan kedudukan isim setelah illa pada Kalam Naqish."}}},{"id_lafadz":"amogenz_lafadz_120","word":"زَيْدٌ","steps":{"1":{"question":"Apa kedudukan زَيْدٌ dalam kalimat ini?","options":["Fa'il","Mustatsna Nashab","Mubtada'"],"correct":"Fa'il","explanation":"Karena ini adalah Istitsna' Mufarragh, maka i'robnya sesuai kebutuhan amil sebelum Illa. 'Qaama' butuh Fa'il."},"2":{"question":"Mengapa ia dibaca Rafa'?","options":["Karena pelaku dari Qaama","Karena isim mufrad","Karena terletak di akhir"],"correct":"Karena pelaku dari Qaama","explanation":"Fa'il adalah isim yang melakukan pekerjaan."},"3":{"question":"Apa tanda i'rob pada زَيْدٌ?","options":["Dhammah","Fathah","Tanwin Kasrah"],"correct":"Dhammah","explanation":"Tanda rafa' asli isim mufrad."},"4":{"question":"Apa istilah untuk pola istitsna' ini?","options":["Mufarragh / Naqish","Taam Mujab","Taam Manfi"],"correct":"Mufarragh / Naqish","explanation":"Disebut mufarragh karena amil sebelum Illa dikosongkan untuk bekerja pada isim setelah Illa."},"5":{"question":"Apakah boleh dibaca 'Zaidan'?","options":["Tidak boleh","Boleh","Wajib"],"correct":"Tidak boleh","explanation":"Dalam pola ini, i'robnya mengikat pada posisi yang dibutuhkan amil."},"6":{"question":"Apa amil yang merofa'kan Zaid?","options":["Fi'il 'Qaama'","Lafadz 'Illa'","Amil Maknawi"],"correct":"Fi'il 'Qaama'","explanation":"Fi'il tetap bekerja mencari pelaku meskipun terhalang oleh Illa."},"7":{"question":"Apakah Zaidun Mu'rob?","options":["Ya, Mu'rob","Mabni"],"correct":"Ya, Mu'rob","explanation":"Isim alam yang menerima tanwin dan perubahan harakat."},"8":{"question":"Kenapa ia disebut Mustatsna?","options":["Karena letaknya setelah Illa","Karena ia berdiri","Karena ia pelaku"],"correct":"Karena letaknya setelah Illa","explanation":"Secara urutan posisi, namun secara i'rob ia mengikuti kebutuhan amil."}}}]},{"id_kalimat":"amogenz_kalimat_032","teks_kalimat":"أَعْجَبَنِي ثَوْبٌ لَوْنُهُ أَحْمَرُ","analysis":[{"id_lafadz":"amogenz_lafadz_122","word":"ثَوْبٌ","steps":{"1":{"question":"Apa kedudukan ثَوْبٌ dalam kalimat ini?","options":["Fa'il","Maf'ul Bih","Mubtada'"],"correct":"Fa'il","explanation":"Ia adalah 'sesuatu' yang membuat kagum (subjek dari rasa kagum)."},"2":{"question":"Lalu, apa kedudukan dhomhir 'Ya' (ي) pada أَعْجَبَنِي?","options":["Maf'ul Bih","Fa'il","Mudhaf Ilaih"],"correct":"Maf'ul Bih","explanation":"Dhomhir mutakallim tersebut adalah objek yang terkena rasa kagum (aku)."},"3":{"question":"Apa hukum i'rob bagi ثَوْبٌ?","options":["Rafa'","Nashab","Jarr"],"correct":"Rafa'","explanation":"Fa'il wajib marfu'."},"4":{"question":"Apa tanda i'rob-nya?","options":["Dhammah","Fathah","Sukun"],"correct":"Dhammah","explanation":"Tanda rafa' isim mufrad."},"5":{"question":"Apa fungsi kalimat 'Lawnuhu Ahmar' setelahnya?","options":["Na'at (Sifat) berupa Jumlah","Khabar","Hal"],"correct":"Na'at (Sifat) berupa Jumlah","explanation":"Menjelaskan keadaan atau ciri dari 'baju' tersebut."},"6":{"question":"Mengapa ia disebut Na'at Jumlah?","options":["Karena jatuh setelah isim nakirah","Karena jatuh setelah isim ma'rifat","Karena ada dhomhir"],"correct":"Karena jatuh setelah isim nakirah","explanation":"Kaidah: Al-Jumlah ba'da al-nakirati shifatun (Kalimat setelah isim nakirah adalah sifat)."},"7":{"question":"Apa status Mahal dari kalimat 'Lawnuhu Ahmar'?","options":["Fi Mahalli Raf'in","Fi Mahalli Nashbin","Fi Mahalli Jarrin"],"correct":"Fi Mahalli Raf'in","explanation":"Karena ia menyifati 'Thaubun' yang sedang marfu'."},"8":{"question":"Apakah 'Thaubun' Mu'rob?","options":["Ya, Mu'rob","Mabni"],"correct":"Ya, Mu'rob","explanation":"Isim mufrad yang menerima tanwin."}}}]},{"id_kalimat":"amogenz_kalimat_033","teks_kalimat":"كُتِبَ الدَّرْسُ بِخَطٍّ وَاضِحٍ","analysis":[{"id_lafadz":"amogenz_lafadz_125","word":"كُتِبَ","steps":{"1":{"question":"Apa jenis fi'il dari كُتِبَ?","options":["Fi'il Madhi Mabni lil Majhul (Pasif)","Fi'il Madhi Mabni lil Ma'lum (Aktif)","Fi'il Mudhari'"],"correct":"Fi'il Madhi Mabni lil Majhul (Pasif)","explanation":"Dilihat dari polanya: dhomma awaluhu wa kusira maa qabla akhirih (didhommah awalnya, dikasrah sebelum akhir)."},"2":{"question":"Apa arti dari كُتِبَ?","options":["Ditulis","Menulis","Tulislah"],"correct":"Ditulis","explanation":"Bentuk pasif yang tidak menyebutkan siapa penulisnya."},"3":{"question":"Apa status i'robnya?","options":["Mabni 'alal Fathi","Mu'rob Rafa'","Mabni 'alas Sukun"],"correct":"Mabni 'alal Fathi","explanation":"Fi'il madhi yang tidak bersambung dengan apapun."},"4":{"question":"Siapakah pelaku (Fa'il) dalam fi'il majhul?","options":["Dibuang/Disembunyikan","Ad-Darsu","Zaid"],"correct":"Dibuang/Disembunyikan","explanation":"Fi'il majhul adalah kata kerja yang subjek aslinya tidak disebutkan."},"5":{"question":"Apa istilah untuk pengganti subjek setelah fi'il pasif?","options":["Naibul Fa'il","Fa'il","Maf'ul Bih"],"correct":"Naibul Fa'il","explanation":"Isim yang menggantikan posisi pelaku yang dibuang."},"6":{"question":"Apa hukum i'rob bagi Naibul Fa'il?","options":["Rafa'","Nashab","Jarr"],"correct":"Rafa'","explanation":"Ia mengambil hukum asal fa'il yaitu marfu'."},"7":{"question":"Apakah 'Kutiba' Mu'rob?","options":["Tidak, Mabni","Ya, Mu'rob"],"correct":"Tidak, Mabni","explanation":"Sesuai kaidah fi'il madhi."},"8":{"question":"Disebut pola apakah 'Kutiba'?","options":["Fi'il Mabni lil Maf'ul","Fi'il Mabni lil Fa'il","Fi'il Mudhari'"],"correct":"Fi'il Mabni lil Maf'ul","explanation":"Istilah lain untuk Fi'il Majhul."}}},{"id_lafadz":"amogenz_lafadz_126","word":"الدَّرْسُ","steps":{"1":{"question":"Apa kedudukan الدَّرْسُ dalam kalimat ini?","options":["Naibul Fa'il","Fa'il","Maf'ul Bih"],"correct":"Naibul Fa'il","explanation":"Karena jatuh setelah fi'il majhul (Kutiba) dan ia adalah 'apa' yang ditulis."},"2":{"question":"Apa hukum i'rob bagi Naibul Fa'il?","options":["Rafa'","Nashab","Jarr"],"correct":"Rafa'","explanation":"Naibul Fa'il wajib marfu' sebagaimana fa'il."},"3":{"question":"Apa tanda i'rob pada الدَّرْسُ?","options":["Dhammah","Fathah","Kasrah"],"correct":"Dhammah","explanation":"Tanda rafa' asli isim mufrad."},"4":{"question":"Mengapa ia disebut Naibul Fa'il?","options":["Menggantikan Fa'il yang dibuang","Karena ia objek","Karena berada setelah fi'il"],"correct":"Menggantikan Fa'il yang dibuang","explanation":"Sebelum dipasifkan, ia adalah Maf'ul Bih (pelajaran), namun setelah pasif ia naik pangkat menjadi Naibul Fa'il."},"5":{"question":"Apakah ia Mu'rob?","options":["Ya, Mu'rob","Mabni"],"correct":"Ya, Mu'rob","explanation":"Isim mufrad yang bisa berubah harakat akhirnya."},"6":{"question":"Apa tanda isim pada lafadz ini?","options":["Alif Lam (Al)","Tanwin","Ta' Marbuthah"],"correct":"Alif Lam (Al)","explanation":"Adanya Al di awal kata."},"7":{"question":"Siapa yang merofa'kan Naibul Fa'il?","options":["Fi'il Majhul (Kutiba)","Mubtada","Amil Maknawi"],"correct":"Fi'il Majhul (Kutiba)","explanation":"Fi'il pasif bekerja memberikan rafa' pada pengganti subjek."},"8":{"question":"Mengapa ia Ma'rifat?","options":["Karena ada AL","Karena ia subjek","Karena isim mufrad"],"correct":"Karena ada AL","explanation":"Alif lam memberikan arti khusus/tertentu."}}}]},{"id_kalimat":"amogenz_kalimat_034","teks_kalimat":"يَا سِيبَوَيْهِ أَقْبِلْ مُسْرِعًا","analysis":[{"id_lafadz":"amogenz_lafadz_130","word":"سِيبَوَيْهِ","steps":{"1":{"question":"Apa kedudukan سِيبَوَيْهِ dalam kalimat ini?","options":["Munada (Yang dipanggil)","Mubtada","Fa'il"],"correct":"Munada (Yang dipanggil)","explanation":"Ia jatuh setelah huruf nida' (Ya)."},"2":{"question":"Apa kategori Munada pada lafadz ini?","options":["Munada Mufrad 'Alam","Munada Mudhaf","Nakirah Maqshudah"],"correct":"Munada Mufrad 'Alam","explanation":"Ia adalah nama orang (Isim Alam) yang bukan berupa susunan penyandaran."},"3":{"question":"Apakah lafadz سِيبَوَيْهِ Mu'rob atau Mabni?","options":["Mabni","Mu'rob"],"correct":"Mabni","explanation":"Isim-isim yang berakhiran '-waihi' secara asal adalah mabni kasrah."},"4":{"question":"Berapakah kemabnian yang dimiliki lafadz ini?","options":["Mabni Kasrah (Asal) & Mabni Dhammah (Munada)","Mabni Fathah saja","Mabni Sukun"],"correct":"Mabni Kasrah (Asal) & Mabni Dhammah (Munada)","explanation":"Secara kata ia mabni kasrah, namun sebagai munada ia dihukumi mabni dhommah muqoddar."},"5":{"question":"Apa Mahal I'rob dari lafadz ini?","options":["Fi Mahalli Nashbin","Fi Mahalli Raf'in","Fi Mahalli Jarrin"],"correct":"Fi Mahalli Nashbin","explanation":"Munada pada hakikatnya adalah Maf'ul Bih (objek yang dipanggil)."},"6":{"question":"Mengapa ia Mabni?","options":["Kaidah Isim Alam berakhiran -waihi","Karena diawali Ya","Karena ia ulama"],"correct":"Kaidah Isim Alam berakhiran -waihi","explanation":"Kata-kata seperti Sibawaih, Nifthawaih, dsb adalah isim mabni."},"7":{"question":"Apa tanda kemabnian aslinya?","options":["Kasrah","Dhammah","Sukun"],"correct":"Kasrah","explanation":"Sibawai-hi (selalu berakhir kasrah)."},"8":{"question":"Apa kedudukan Munada 'Alam secara umum?","options":["Mabni 'ala ma yurfa'u bihi","Wajib Nashab Tanwin","Majrur"],"correct":"Mabni 'ala ma yurfa'u bihi","explanation":"Kaidah munada mufrod alam adalah mabni dhommah."}}},{"id_lafadz":"amogenz_lafadz_132","word":"مُسْرِعًا","steps":{"1":{"question":"Apa kedudukan مُسْرِعًا dalam kalimat ini?","options":["Hal (Keterangan Keadaan)","Tamyiz","Maf'ul Bih"],"correct":"Hal (Keterangan Keadaan)","explanation":"Menjelaskan keadaan subjek saat melakukan perbuatan (datang dalam keadaan cepat)."},"2":{"question":"Apa hukum i'rob bagi Hal?","options":["Nashab","Rafa'","Jarr"],"correct":"Nashab","explanation":"Hal adalah bagian dari Manshubatul Asma."},"3":{"question":"Apa tanda i'rob pada مُسْرِعًا?","options":["Fathah","Kasrah","Dhammah"],"correct":"Fathah","explanation":"Tanda nashab asli bagi isim mufrad."},"4":{"question":"Apa syarat isim untuk menjadi Hal?","options":["Wajib Nakirah","Wajib Ma'rifat","Wajib Mabni"],"correct":"Wajib Nakirah","explanation":"Kaidah: Al-Haalu laa takuunu illa nakiratan."},"5":{"question":"Siapakah 'Shahibul Hal' (pemilik keadaan) di sini?","options":["Dhomir Mustatir pada Aqbil","Sibawaih","Huruf Ya"],"correct":"Dhomir Mustatir pada Aqbil","explanation":"Keadaan tersebut merujuk pada subjek 'kamu' dalam kata perintah 'Aqbil'."},"6":{"question":"Apa syarat Shahibul Hal?","options":["Wajib Ma'rifat","Wajib Nakirah","Wajib Jamak"],"correct":"Wajib Ma'rifat","explanation":"Pemilik keadaan harus sudah jelas/diketahui."},"7":{"question":"Apakah مُسْرِعًا Mu'rob?","options":["Ya, Mu'rob","Mabni"],"correct":"Ya, Mu'rob","explanation":"Dapat menerima perubahan harakat."},"8":{"question":"Apa jenis Hal ini?","options":["Hal Mufradah","Hal Jumlah","Hal Syibhu Jumlah"],"correct":"Hal Mufradah","explanation":"Karena terdiri dari satu kata tunggal (bukan kalimat/paragraf)."}}}]},{"id_kalimat":"amogenz_kalimat_035","teks_kalimat":"سِرْتُ وَشَاطِئَ الْبَحْرِ","analysis":[{"id_lafadz":"amogenz_lafadz_133","word":"وَ","steps":{"1":{"question":"Apa jenis huruf 'Wawu' pada kalimat ini?","options":["Wawu Athaf","Wawu Ma'iyah","Wawu Hal"],"correct":"Wawu Ma'iyah","explanation":"Wawu di sini bermakna 'ma'a' (beserta/sepanjang), menunjukkan kebersamaan waktu, bukan menyatukan hukum pekerjaan antara dua pihak."},"2":{"question":"Apa syarat Wawu disebut Ma'iyah?","options":["Didahului oleh kalimat (jumlah)","Harus bermakna 'dan'","Harus di awal kalimat"],"correct":"Didahului oleh kalimat (jumlah)","explanation":"Wawu Ma'iyah harus didahului oleh sebuah pernyataan (jumlah) yang sempurna."},"3":{"question":"Apakah Wawu ini Mu'rob atau Mabni?","options":["Mabni","Mu'rob"],"correct":"Mabni","explanation":"Semua huruf dalam kaidah Nahwu bersifat Mabni."},"4":{"question":"Apa dasar kemabnian Wawu ini?","options":["Mabni 'alal Fathi","Mabni 'alas Sukun","Mabni 'alad Dhammi"],"correct":"Mabni 'alal Fathi","explanation":"Huruf Wawu selalu berharakat fathah (Wa)."},"5":{"question":"Apa dampak Wawu Ma'iyah terhadap isim setelahnya?","options":["Menashabkan sebagai Maf'ul Ma'ah","Merofa'kan","Menjarrkan"],"correct":"Menashabkan sebagai Maf'ul Ma'ah","explanation":"Isim yang jatuh setelah Wawu Ma'iyah wajib dibaca Nashab."},"6":{"question":"Mengapa tidak disebut Wawu Athaf?","options":["Karena pantai tidak ikut berjalan","Karena pantai adalah tempat","Karena ada alif lam"],"correct":"Karena pantai tidak ikut berjalan","explanation":"Secara logika, 'Pantai' tidak melakukan pekerjaan 'berjalan' (Sir-tu), sehingga tidak bisa diathafkan kepada subjek."},"7":{"question":"Apa kedudukan I'robnya?","options":["Laa Mahalla Laha","Fi Mahalli Nashbin","Fi Mahalli Raf'in"],"correct":"Laa Mahalla Laha","explanation":"Huruf tidak memiliki mahal i'rob."},"8":{"question":"Bermakna apakah Wawu ini?","options":["Ma'a (Bersama)","Wa (Dan)","Likin (Tetapi)"],"correct":"Ma'a (Bersama)","explanation":"Artinya: 'Aku berjalan bersamaan/sepanjang pantai'."}}},{"id_lafadz":"amogenz_lafadz_134","word":"شَاطِئَ","steps":{"1":{"question":"Apa kedudukan شَاطِئَ dalam kalimat ini?","options":["Maf'ul Ma'ah","Maf'ul Bih","Athaf"],"correct":"Maf'ul Ma'ah","explanation":"Isim yang disebut setelah Wawu Ma'iyah untuk menjelaskan pihak yang menyertai perbuatan."},"2":{"question":"Apa hukum I'rob bagi Maf'ul Ma'ah?","options":["Nashab","Rafa'","Jarr"],"correct":"Nashab","explanation":"Maf'ul Ma'ah termasuk dalam jajaran Manshubatul Asma (Isim-isim yang wajib Nashab)."},"3":{"question":"Apa tanda Nashab pada lafadz شَاطِئَ?","options":["Fathah","Ya","Alif"],"correct":"Fathah","explanation":"Tanda nashab asli untuk isim mufrad."},"4":{"question":"Apakah lafadz ini Mu'rob atau Mabni?","options":["Mu'rob","Mabni"],"correct":"Mu'rob","explanation":"Harakat akhirnya berubah karena pengaruh amil (Wawu Ma'iyah)."},"5":{"question":"Mengapa tidak bertanwin?","options":["Karena Mudhaf","Karena Ghairu Munsharif","Karena ada Al"],"correct":"Karena Mudhaf","explanation":"Lafadz ini disandarkan kepada Al-Bahri, dan Mudhaf tidak boleh bertanwin."},"6":{"question":"Apa amil yang menashabkannya?","options":["Fi'il (Sir-tu) melalui perantara Wawu","Wawu saja","Amil Maknawi"],"correct":"Fi'il (Sir-tu) melalui perantara Wawu","explanation":"Kekuatan nashab berasal dari kata kerja sebelumnya."},"7":{"question":"Apa arti dari شَاطِئَ?","options":["Pantai/Pinggir","Tengah","Ombak"],"correct":"Pantai/Pinggir","explanation":"Secara bahasa berarti tepian laut."},"8":{"question":"Termasuk kategori apakah Maf'ul Ma'ah?","options":["Fadhilah (Pelengkap)","Umdah (Pokok)","Sifat"],"correct":"Fadhilah (Pelengkap)","explanation":"Unsur tambahan dalam kalimat yang memberikan keterangan lebih lanjut."}}}]},{"id_kalimat":"amogenz_kalimat_036","teks_kalimat":"لَمْ يَقْضِ الْقَاضِي بِالْحَقِّ","analysis":[{"id_lafadz":"amogenz_lafadz_136","word":"يَقْضِ","steps":{"1":{"question":"Apa jenis fi'il dari يَقْضِ?","options":["Fi'il Mudhari'","Fi'il Madhi","Fi'il Amr"],"correct":"Fi'il Mudhari'","explanation":"Diawali huruf mudhara'ah 'Ya' dan menunjukkan perbuatan yang sedang/akan berlangsung."},"2":{"question":"Apa kedudukan I'rob يَقْضِ?","options":["Jazm","Nashab","Rafa'"],"correct":"Jazm","explanation":"Lafadz ini didahului oleh amil jazm yaitu 'Lam' (Huruf Nafyi wa Jazm wa Qalb)."},"3":{"question":"Apa tanda Jazm pada يَقْضِ?","options":["Hazfu Harfil 'Illah","Sukun","Hazfun Nuun"],"correct":"Hazfu Harfil 'Illah","explanation":"Tanda jazm-nya adalah dengan membuang huruf illat (Ya') di akhir kata."},"4":{"question":"Mengapa tandanya membuang huruf illat?","options":["Karena Fi'il Mudhari' Mu'tal Akhir","Karena Af'alul Khomsah","Karena Shahih Akhir"],"correct":"Karena Fi'il Mudhari' Mu'tal Akhir","explanation":"Asal katanya adalah 'Yaqdhii' (يَقْضِي), berakhir dengan huruf illat Ya'."},"5":{"question":"Apa fungsi 'Lam' terhadap makna fi'il ini?","options":["Menafikan dan membalik waktu ke lampau","Melarang","Memerintah"],"correct":"Menafikan dan membalik waktu ke lampau","explanation":"Lam mengubah makna mudhari' menjadi lampau (Tidak telah memutuskan)."},"6":{"question":"Apakah harakat kasrah pada 'Dhad' adalah tanda I'rob?","options":["Bukan, itu harakat asli","Ya, tanda Jarr","Tanda Jazm"],"correct":"Bukan, itu harakat asli","explanation":"Kasrah tetap ada untuk menunjukkan bahwa ada huruf 'Ya' yang dibuang."},"7":{"question":"Apakah يَقْضِ Mu'rob?","options":["Ya, Mu'rob","Mabni"],"correct":"Ya, Mu'rob","explanation":"Fi'il mudhari' adalah mu'rob selama tidak bertemu Nun Taukid/Niswah."},"8":{"question":"Apa istilah teknis pembuangan huruf ini?","options":["Hazfu Harfil 'Illah","I'lal","Idgham"],"correct":"Hazfu Harfil 'Illah","explanation":"Istilah baku dalam kitab-kitab Nahwu."}}}]},{"id_kalimat":"amogenz_kalimat_037","teks_kalimat":"عَنِ النَّبَأِ الْعَظِيمِ يَتَسَاءَلُونَ","analysis":[{"id_lafadz":"amogenz_lafadz_142","word":"يَتَسَاءَلُونَ","steps":{"1":{"question":"Apa jenis fi'il dari يَتَسَاءَلُونَ?","options":["Fi'il Mudhari' (Af'alul Khomsah)","Fi'il Madhi","Isim"],"correct":"Fi'il Mudhari' (Af'alul Khomsah)","explanation":"Fi'il mudhari' yang bersambung dengan Wawu Jamak."},"2":{"question":"Apa kedudukan I'rob يَتَسَاءَلُونَ?","options":["Rafa'","Nashab","Jarr"],"correct":"Rafa'","explanation":"Lafadz ini tidak didahului amil nashab maupun amil jazm."},"3":{"question":"Apa tanda Rafa' bagi Af'alul Khomsah?","options":["Thubutun Nuun (Tetapnya Nun)","Dhammah","Wawu"],"correct":"Thubutun Nuun (Tetapnya Nun)","explanation":"Tanda rafa'-nya adalah adanya huruf Nun di akhir kata."},"4":{"question":"Apa fungsi Wawu (و) pada kata tersebut?","options":["Dhamir (Fa'il)","Huruf Athaf","Tanda Jamak Isim"],"correct":"Dhamir (Fa'il)","explanation":"Wawu tersebut adalah kata ganti subjek (Mereka) yang berkedudukan Rafa' sebagai Fa'il."},"5":{"question":"Apakah Nun tersebut akan hilang?","options":["Ya, saat Nashab atau Jazm","Tidak, selalu ada","Hanya saat bertemu Al"],"correct":"Ya, saat Nashab atau Jazm","explanation":"Af'alul Khomsah membuang Nun (Hazfun Nuun) sebagai tanda Nashab/Jazm."},"6":{"question":"Apa wazan dari يَتَسَاءَلُونَ?","options":["Yatafaa'aluuna","Yaf'aluuna","Yatafa''aluuna"],"correct":"Yatafaa'aluuna","explanation":"Mengikuti pola pertambahan huruf Ta dan Alif (Tafaa'ala)."},"7":{"question":"Dimana letak Fa'ilnya?","options":["Wawu Jamak","Dhomir Mustatir","An-Naba'"],"correct":"Wawu Jamak","explanation":"Subjeknya melekat pada fi'il berupa dhomir bariz (nampak)."},"8":{"question":"Apakah ia Mu'rob?","options":["Ya, Mu'rob dengan Huruf","Mabni","Mu'rob dengan Harakat"],"correct":"Ya, Mu'rob dengan Huruf","explanation":"I'robnya menggunakan tetap atau hilangnya Nun."}}}]},{"id_kalimat":"amogenz_kalimat_038","teks_kalimat":"مَرَرْتُ بِصَحْرَاءَ وَاسِعَةِ الْأرجَاءِ","analysis":[{"id_lafadz":"amogenz_lafadz_144","word":"بِصَحْرَاءَ","steps":{"1":{"question":"Apa fungsi huruf 'Ba' (بِ)?","options":["Huruf Jarr","Huruf Athaf","Zaidah"],"correct":"Huruf Jarr","explanation":"Berfungsi menjarrkan isim setelahnya."},"2":{"question":"Apa kedudukan I'rob صَحْرَاءَ?","options":["Jarr","Nashab","Rafa'"],"correct":"Jarr","explanation":"Karena didahului huruf jarr."},"3":{"question":"Apa tanda Jarr pada صَحْرَاءَ?","options":["Fathah","Kasrah","Ya"],"correct":"Fathah","explanation":"Ia dijarrkan dengan fathah karena merupakan Isim Ghairu Munsharif."},"4":{"question":"Mengapa ia Ghairu Munsharif?","options":["Alif Ta'nits Mamdudah","Alif Ta'nits Maqshurah","Wazan Fi'il"],"correct":"Alif Ta'nits Mamdudah","explanation":"Lafadz yang diakhiri Alif dan Hamzah tambahan untuk menunjukkan sifat/benda muannats."},"5":{"question":"Berapa 'illat (alasan) pada lafadz ini?","options":["Satu 'illat menempati posisi dua","Dua 'illat","Tiga 'illat"],"correct":"Satu 'illat menempati posisi dua","explanation":"Alif Ta'nits Mamdudah adalah illat tunggal yang cukup kuat untuk menghalangi tanwin."},"6":{"question":"Apakah ia boleh menerima Tanwin?","options":["Tidak boleh","Boleh","Wajib"],"correct":"Tidak boleh","explanation":"Ghairu Munsharif dilarang bertanwin."},"7":{"question":"Apa syarat ia boleh dibaca Kasrah?","options":["Jika ada AL atau jadi Mudhaf","Jika diawali Lam","Jika di akhir kalimat"],"correct":"Jika ada AL atau jadi Mudhaf","explanation":"Hukum Ghairu Munsharif batal jika ia beralif-lam atau disandarkan."},"8":{"question":"Apa status 'Waasi'ati' setelahnya?","options":["Na'at (Sifat)","Mudhaf Ilaih","Khabar"],"correct":"Na'at (Sifat)","explanation":"Menjelaskan sifat padang pasir (yang luas)."},"9":{"question":"Jelaskan Alif Ta'nits Mamdudah pada Sahra'!","options":["Alif + Hamzah tambahan di akhir kata","Alif bengkok di akhir","Hamzah di awal"],"correct":"Alif + Hamzah tambahan di akhir kata","explanation":"Pola (---aa-') yang bukan merupakan huruf asli akar kata (S-Kh-R)."}}}]},{"id_kalimat":"amogenz_kalimat_039","teks_kalimat":"إِيَّاكَ وَالْكَذِبَ يَا صَدِيقِي","analysis":[{"id_lafadz":"amogenz_lafadz_147","word":"إِيَّاكَ","steps":{"1":{"question":"Apa jenis kata إِيَّاكَ?","options":["Dhamir Munfashil","Isim Isyarah","Isim Fi'il"],"correct":"Dhamir Munfashil","explanation":"Kata ganti terpisah yang khusus untuk posisi Nashab."},"2":{"question":"Apa fungsi kalimat ini secara keseluruhan?","options":["Tahdzir (Peringatan)","Ighra' (Ajakan)","Nida'"],"correct":"Tahdzir (Peringatan)","explanation":"Berfungsi memperingatkan seseorang agar menjauhi sesuatu (kebohongan)."},"3":{"question":"Apa kedudukan I'rob إِيَّاكَ?","options":["Fi Mahalli Nashbin (Maf'ul Bih)","Fi Mahalli Raf'in","Mabni Fathah"],"correct":"Fi Mahalli Nashbin (Maf'ul Bih)","explanation":"Berposisi sebagai objek dari fi'il yang dibuang (Taqdirnya: Ihdzar/Jauhilah)."},"4":{"question":"Apakah إِيَّاكَ Mu'rob atau Mabni?","options":["Mabni","Mu'rob"],"correct":"Mabni","explanation":"Semua jenis dhamir adalah mabni."},"5":{"question":"Terdiri dari apa lafadz إِيَّاكَ?","options":["Iyya (Dhamir) + Ka (Huruf Khitab)","Satu kata utuh","Iyya + Ka (Mudhaf Ilaih)"],"correct":"Iyya (Dhamir) + Ka (Huruf Khitab)","explanation":"Iyya adalah intinya, Kaf hanya penunjuk lawan bicara (kamu)."},"6":{"question":"Apa kedudukan 'Al-Kadziba' (الْكَذِبَ) setelahnya?","options":["Maf'ul Bih dari fi'il yang dibuang","Athaf","Sifat"],"correct":"Maf'ul Bih dari fi'il yang dibuang","explanation":"Meskipun ada Wawu, ia tetap Nashab karena diperingatkan untuk dijauhi (Taqdir: Wa i'tazilil kadziba)."},"7":{"question":"Apa tanda kemabnian 'Iyya'?","options":["Mabni 'alas Sukun","Mabni 'alal Fathi","Mabni 'alad Dhammi"],"correct":"Mabni 'alas Sukun","explanation":"Berakhir dengan alif."},"8":{"question":"Disebut apakah pola penyebutan objek peringatan ini?","options":["Tahdzir","Ikhbar","Ikhtishash"],"correct":"Tahdzir","explanation":"Gaya bahasa peringatan dalam sastra Arab."}}}]},{"id_kalimat":"amogenz_kalimat_040","teks_kalimat":"مَنْ يَجْتَهِدْ يَنَلْ مُرَادَهُ","analysis":[{"id_lafadz":"amogenz_lafadz_150","word":"مَنْ","steps":{"1":{"question":"Apa jenis kata مَنْ dalam konteks kalimat ini?","options":["Isim Syarat","Isim Istifham","Isim Maushul"],"correct":"Isim Syarat","explanation":"Ia berfungsi menghubungkan dua perbuatan, di mana perbuatan pertama menjadi syarat bagi terjadinya perbuatan kedua."},"2":{"question":"Apa fungsi amalan dari مَنْ Syarthiyah?","options":["Menjazmkan dua Fi'il Mudhari'","Menjazmkan satu Fi'il Mudhari'","Menashabkan Isim"],"correct":"Menjazmkan dua Fi'il Mudhari'","explanation":"Ia termasuk 'Adawatul Jaza' yang menjazmkan Fi'il Syarat dan Jawab Syarat."},"3":{"question":"Apakah مَنْ Mu'rob atau Mabni?","options":["Mabni","Mu'rob"],"correct":"Mabni","explanation":"Hukum asal Isim Syarat adalah mabni, dalam hal ini mabni di atas sukun."},"4":{"question":"Apa kedudukan (mahal) I'rob مَنْ di sini?","options":["Fi mahalli raf'in (Mubtada')","Fi mahalli nashbin (Maf'ul)","Laa mahalla lahu"],"correct":"Fi mahalli raf'in (Mubtada')","explanation":"Jika isim syarat diikuti fi'il lazim atau fi'il muta'addi yang sudah mengambil objeknya, ia berkedudukan sebagai Mubtada'."},"5":{"question":"Apa tanda kemabniannya?","options":["Sukun","Fathah","Dhammah"],"correct":"Sukun","explanation":"Lafadz Man berakhir dengan nun mati/sukun."},"6":{"question":"Apa istilah untuk kalimat pertama setelah مَنْ?","options":["Fi'il Syarat","Jawab Syarat","Khabar"],"correct":"Fi'il Syarat","explanation":"Perbuatan yang menjadi prasyarat."},"7":{"question":"Apa istilah untuk kalimat kedua?","options":["Jawab Syarat","Sifat","Hal"],"correct":"Jawab Syarat","explanation":"Hasil atau konsekuensi dari syarat yang terpenuhi."},"8":{"question":"Mengapa مَنْ disebut amil jawazim?","options":["Karena merubah harakat menjadi sukun","Karena mengawali kalimat","Karena bermakna 'siapa'"],"correct":"Karena merubah harakat menjadi sukun","explanation":"Secara struktural ia menuntut fi'il setelahnya berstatus Jazm."}}},{"id_lafadz":"amogenz_lafadz_151","word":"يَجْتَهِدْ","steps":{"1":{"question":"Apa kedudukan يَجْتَهِدْ dalam struktur syarat?","options":["Fi'il Syarat","Jawab Syarat","Khabar"],"correct":"Fi'il Syarat","explanation":"Perbuatan inti yang menjadi syarat."},"2":{"question":"Apa status I'rob dari يَجْتَهِدْ?","options":["Jazm","Rafa'","Nashab"],"correct":"Jazm","explanation":"Dijazmkan oleh Isim Syarat 'Man'."},"3":{"question":"Apa tanda Jazm pada يَجْتَهِدْ?","options":["Sukun","Hazfu Nuun","Hazfu Harfil Illah"],"correct":"Sukun","explanation":"Tanda asli jazm untuk fi'il mudhari' shahih akhir."},"4":{"question":"Mengapa tandanya Sukun?","options":["Karena Shahih Akhir","Karena Mu'tal Akhir","Karena Af'alul Khomsah"],"correct":"Karena Shahih Akhir","explanation":"Huruf akhirnya 'Dal' bukan merupakan huruf illat."},"5":{"question":"Siapa pelaku (Fa'il) dari يَجْتَهِدْ?","options":["Dhamir Mustatir (Huwa)","Lafadz Man","Lafadz Yanal"],"correct":"Dhamir Mustatir (Huwa)","explanation":"Subjeknya tersimpan secara tersembunyi yang kembali kepada 'Man'."},"6":{"question":"Apa wazan dari kata ini?","options":["Yafta'ilu","Yaf'ulu","Yatafa''alu"],"correct":"Yafta'ilu","explanation":"Berasal dari Mujarrad 'Jahada' yang mengikuti pola Ifta'ala."},"7":{"question":"Apakah kata ini Mu'rob?","options":["Ya, Mu'rob","Mabni"],"correct":"Ya, Mu'rob","explanation":"Fi'il mudhari' yang dapat berubah harakat akhirnya."},"8":{"question":"Apa dampak makna dari Jazm di sini?","options":["Menunjukkan kepastian syarat","Menunjukkan larangan","Menunjukkan waktu lampau"],"correct":"Menunjukkan kepastian syarat","explanation":"Mengikat perbuatan 'sungguh-sungguh' dengan 'pencapaian'."}}},{"id_lafadz":"amogenz_lafadz_152","word":"يَنَلْ","steps":{"1":{"question":"Apa kedudukan يَنَلْ dalam kalimat ini?","options":["Jawab Syarat / Jaza'","Fi'il Syarat","Na'at"],"correct":"Jawab Syarat / Jaza'","explanation":"Hasil yang diperoleh jika syarat terpenuhi."},"2":{"question":"Apa status I'rob dari يَنَلْ?","options":["Jazm","Rafa'","Nashab"],"correct":"Jazm","explanation":"Karena ia merupakan Jawab Syarat dari amil 'Man'."},"3":{"question":"Apa tanda Jazm pada يَنَلْ?","options":["Sukun","Hazfu Harfil Illah","Fathah"],"correct":"Sukun","explanation":"Tanda sukun nampak pada huruf Lam."},"4":{"question":"Berasal dari kata apakah يَنَلْ?","options":["Yanaalu","Yaniluu","Yanuluu"],"correct":"Yanaalu","explanation":"Asalnya adalah Yanaalu (يَنَالُ) dengan huruf Alif sebelum Lam."},"5":{"question":"Mengapa huruf Alif pada 'Yanaalu' hilang menjadi 'Yanal'?","options":["Pertemuan dua sukun (Iltiqa'us Sakinaini)","Dibuang karena amil jazm","Idgham"],"correct":"Pertemuan dua sukun (Iltiqa'us Sakinaini)","explanation":"Alif (sukun) bertemu Lam yang disukunkan karena Jazm. Alif dibuang untuk memudahkan pengucapan."},"6":{"question":"Apakah ini termasuk Hazfu Harfil Illah?","options":["Bukan","Ya"],"correct":"Bukan","explanation":"Hazfu Harfil Illah hanya terjadi jika huruf illat berada di akhir kata (Lammul Fi'li), sedangkan Alif di sini adalah 'Ainul Fi'li."},"7":{"question":"Siapa Fa'ilnya?","options":["Dhamir Mustatir (Huwa)","Muraadahu","Man"],"correct":"Dhamir Mustatir (Huwa)","explanation":"Pelakunya tersembunyi."},"8":{"question":"Apa kedudukan 'Muraadahu' setelahnya?","options":["Maf'ul Bih","Fa'il","Tamyiz"],"correct":"Maf'ul Bih","explanation":"Objek yang dicapai (keinginannya)."}}}]}];
